for inst in qc.data:
    op = inst.operation
    if op.name in ("for_loop", "while_loop", "switch_case"):
        return False
    if op.name == "if_else":
        if dentro or getattr(op.condition[0], "size", 1) > 32:
            return False
        if not all(es_valido(b, dentro=True) for b in op.blocks):
            return False
    elif dentro and op.name in ("measure", "reset"):
        return False
return True
